// Pure rule engine: digest (from the indexer) + live session data -> findings.
// No mods API calls here, so it can be imported and unit-tested freely. Every builder takes a
// ctx from i18n.js (language, strings, doc links, user rule settings); omitted, it is English
// with the default rules.

import { makeCtx } from './i18n.js'

export const THRESHOLDS = {
  contextWarnPct: 60,
  contextHighPct: 80,
  rateLimitWarnPct: 80,
  compactHighTokens: 700_000,
  heavySessions: 3,
  heavyShareHigh: 0.5,
  unreviewedEdits: 3,
  reviewerRatioLow: 0.1,
  correctionHigh: 10,
  correctionShare: 0.02,
  longTurnMs: 30 * 60 * 1000,
  toolErrorsHigh: 100,
  cheapShareLow: 0.15,
}

// Kept in step with RISKY_PATTERNS in indexer/chronicle_index.py.
export const RISKY_COMMANDS = [
  [/\brm\s+-\w*r/, 'rm -r'],
  [/git\s+push\b.*(\s-f\b|--force(?!-with-lease))/, 'force push'],
  [/git\s+reset\s+--hard/, 'reset --hard'],
  [/(^|[\s;&|])(ssh|scp|rsync)\s/, 'remote copy/shell'],
  [/(^|[\s;&|])sudo\s/, 'sudo'],
]
const CODE_EXTS = new Set(['.ts', '.tsx', '.js', '.jsx', '.mjs', '.cjs', '.py', '.rs', '.go', '.swift', '.kt', '.java', '.c', '.cpp', '.cs', '.rb'])

const sum = (xs) => xs.reduce((a, b) => a + b, 0)
const fmt = (n) => (n >= 1e9 ? (n / 1e9).toFixed(1) + 'B' : n >= 1e6 ? (n / 1e6).toFixed(1) + 'M' : n >= 1e3 ? (n / 1e3).toFixed(0) + 'k' : String(n))
const finding = (f) => ({ severity: 'mid', details: [], ...f })
const DETAIL_ROWS = 6
const TRIGGERS = new Set(['auto', 'manual'])
const pct = (n, total) => (total ? Math.round((n / total) * 100) : 0)
const basename = (p) => String(p || '?').split(/[\\/]/).filter(Boolean).pop() || '?'
const sessionLabel = (s) => `${basename(s.project)} ${String(s.end || '').slice(5, 10)}`
// Details are built from counts, model names, dates and project folder names only.
const topSessions = (digest, score, render) => (digest?.sessions || [])
  .map((s) => ({ s, v: score(s) })).filter((r) => r.v > 0)
  .sort((a, b) => b.v - a.v).slice(0, DETAIL_ROWS).map(render)

export function isCodePath(path) {
  const dot = path.lastIndexOf('.')
  return dot >= 0 && CODE_EXTS.has(path.slice(dot).toLowerCase())
}

// A plugin-scoped agent (`my-plugin:code-reviewer`) counts by its last segment.
export function isReviewer(agentType, reviewers) {
  return reviewers.includes(String(agentType || '').split(':').pop())
}

// Built-in risky commands plus the user's extra substrings (labelled by the substring itself).
export function riskyCommands(cfg) {
  const escape = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
  const builtIn = new Set(RISKY_COMMANDS.map(([, label]) => label))
  // A string equal to a built-in label would count the same command twice.
  return [...RISKY_COMMANDS, ...cfg.extraRisky.filter((s) => !builtIn.has(s)).map((s) => [new RegExp(escape(s)), s])]
}

// Fold every session into one set of totals.
export function totals(digest) {
  const t = { tools: {}, agents: {}, risky: {}, permModes: {}, apiErrors: {}, usage: {}, editExts: {}, bashHeads: {}, compactions: [], turns: [], sessions: 0 }
  const add = (dst, src) => { for (const [k, v] of Object.entries(src || {})) dst[k] = (dst[k] || 0) + v }
  for (const s of digest?.sessions || []) {
    t.sessions += 1
    add(t.tools, s.tools); add(t.agents, s.agents); add(t.risky, s.risky); add(t.bashHeads, s.bashHeads)
    add(t.permModes, s.permModes); add(t.apiErrors, s.apiErrors); add(t.editExts, s.editExts)
    for (const src of [s.usageByModel, s.subUsage]) {
      for (const [model, u] of Object.entries(src || {})) {
        const row = (t.usage[model] ||= { in: 0, out: 0, cacheRead: 0, cacheWrite: 0 })
        for (const k of Object.keys(row)) row[k] += u[k] || 0
      }
    }
    t.compactions.push(...(s.compactions || []))
    if (s.turns?.count) t.turns.push(s.turns)
  }
  return t
}

// Live state after one tool call: code files edited since the last review, risky commands run.
export function trackToolCall(state, e, risky = RISKY_COMMANDS) {
  let next = state
  if ((e.tool === 'Edit' || e.tool === 'Write') && typeof e.file_path === 'string' && isCodePath(e.file_path)) {
    if (!next.unreviewed.includes(e.file_path)) next = { ...next, unreviewed: [...next.unreviewed, e.file_path] }
  }
  if (e.tool === 'Bash' && typeof e.command === 'string') {
    for (const [re, label] of risky) {
      if (re.test(e.command)) next = { ...next, risky: { ...next.risky, [label]: (next.risky[label] || 0) + 1 } }
    }
  }
  return next
}

export function buildNow(live, ctx = makeCtx()) {
  const { t, doc, cfg } = ctx
  const out = []
  const used = live?.context?.percent
  if (typeof used === 'number' && used >= THRESHOLDS.contextWarnPct) {
    out.push(finding({
      id: 'now-context', severity: used >= THRESHOLDS.contextHighPct ? 'high' : 'mid',
      title: t('nowContextTitle', { pct: Math.round(used) }),
      evidence: `${fmt(live.context.tokens || 0)} / ${fmt(live.context.window || 0)} tokens`,
      action: t('nowContextAction'),
      doc: doc('context-window'),
    }))
  }
  for (const rl of live?.rateLimits || []) {
    if (rl.percentUsed < THRESHOLDS.rateLimitWarnPct) continue
    out.push(finding({
      id: 'now-rate-' + rl.kind, severity: 'high',
      title: t('nowRateTitle', { kind: rl.kind, pct: Math.round(rl.percentUsed) }),
      evidence: rl.resetsAt ? t('nowRateResets', { at: rl.resetsAt }) : t('nowRateUnknown'),
      action: t('nowRateAction'),
      doc: doc('costs'),
    }))
  }
  out.push(...unreviewedFindings(live, ctx))
  for (const [label, n] of Object.entries(live?.risky || {})) {
    out.push(finding({
      id: 'now-risky-' + label, severity: 'mid',
      title: t('nowRiskyTitle', { label, n }),
      evidence: t('nowRiskyEvidence'),
      action: t('nowRiskyAction'),
      doc: doc('permissions'),
    }))
  }
  return out
}

function unreviewedFindings(live, { t, cfg }) {
  const pending = live?.unreviewed?.length || 0
  // With no review agents configured there is nothing to recommend running.
  if (pending < THRESHOLDS.unreviewedEdits || !cfg.reviewers.length) return []
  const agents = cfg.reviewers.join(', ')
  return [finding({
    id: 'now-unreviewed', severity: 'high',
    title: t('nowUnreviewedTitle', { n: pending }),
    evidence: live.unreviewed.slice(0, 5).map(basename).join(', '),
    action: t('nowUnreviewedAction', { agents }),
    prompt: t('nowUnreviewedPrompt', { agents }),
    details: live.unreviewed.map(basename),
    // File names stay on this machine: the AI explanation is sent without these details.
    localDetails: true,
  })]
}

export function buildCost(digest, ctx = makeCtx()) {
  const tot = totals(digest)
  return [
    ...lateCompactFindings(tot, ctx),
    ...heavySessionFindings(digest, ctx),
    ...modelMixFindings(tot, ctx),
    ...creditFindings(tot, ctx),
    ...longTurnFindings(digest, tot, ctx),
  ]
}

function lateCompactFindings(tot, { t, doc }) {
  const big = tot.compactions.filter((c) => (c.preTokens || 0) >= THRESHOLDS.compactHighTokens)
  if (!big.length) return []
  return [finding({
    id: 'cost-late-compact', severity: 'high',
    title: t('lateCompactTitle', { big: big.length, all: tot.compactions.length, limit: fmt(THRESHOLDS.compactHighTokens) }),
    evidence: t('lateCompactEvidence', { max: fmt(Math.max(...big.map((c) => c.preTokens))) }),
    action: t('lateCompactAction'),
    doc: doc('model-config'),
    details: big.map((c) => `${String(c.at || '').slice(0, 10)} ${TRIGGERS.has(c.trigger) ? c.trigger : '?'} ${fmt(c.preTokens)} tokens`),
  })]
}

const sessionCacheRead = (s) => sum([s.usageByModel, s.subUsage].flatMap((src) => Object.values(src || {}).map((u) => u.cacheRead || 0)))

// A few very long sessions usually dominate cache reads; name them so they can be split.
// Evidence uses project folder names and dates only, never transcript text.
function heavySessionFindings(digest, { t, doc }) {
  const rows = (digest?.sessions || []).map((s) => ({ s, read: sessionCacheRead(s) })).filter((r) => r.read > 0)
  const total = sum(rows.map((r) => r.read))
  if (!total) return []
  const top = [...rows].sort((a, b) => b.read - a.read).slice(0, THRESHOLDS.heavySessions)
  const share = sum(top.map((r) => r.read)) / total
  return [finding({
    id: 'cost-heavy-sessions', severity: share >= THRESHOLDS.heavyShareHigh ? 'mid' : 'low',
    title: t('heavyTitle', { n: top.length, pct: Math.round(share * 100) }),
    evidence: t('heavyEvidence', { top: top.map((r) => `${sessionLabel(r.s)} ${fmt(r.read)}`).join(' · '), total: fmt(total) }),
    action: t('heavyAction'),
    doc: doc('prompt-caching'),
    details: topSessions(digest, sessionCacheRead, (r) => t('heavyDetail', { label: sessionLabel(r.s), read: fmt(r.v), pct: pct(r.v, total) + '%', n: r.s.compactions?.length || 0 })),
  })]
}

function modelMixFindings(tot, { t, doc }) {
  const outByModel = Object.entries(tot.usage).map(([m, u]) => [m, u.out]).filter(([, n]) => n > 0)
  const total = sum(outByModel.map(([, n]) => n))
  if (!total) return []
  const top = [...outByModel].sort((a, b) => b[1] - a[1]).slice(0, 4)
  const cheap = sum(outByModel.filter(([m]) => /sonnet|haiku/.test(m)).map(([, n]) => n))
  return [finding({
    id: 'cost-model-mix', severity: cheap / total < THRESHOLDS.cheapShareLow ? 'mid' : 'low',
    title: t('mixTitle', { pct: pct(cheap, total) }),
    evidence: top.map(([m, n]) => `${m.replace('claude-', '')} ${pct(n, total)}%`).join(' · '),
    action: t('mixAction'),
    doc: doc('sub-agents'),
    details: outByModel.map(([m, n]) => `${m.replace('claude-', '')}: ${fmt(n)} (${pct(n, total)}%)`),
  })]
}

function creditFindings(tot, { t, doc }) {
  const credits = tot.apiErrors.credits || 0
  if (!credits) return []
  return [finding({
    id: 'cost-credits', severity: 'mid',
    title: t('creditsTitle', { n: credits }),
    evidence: t('creditsEvidence', { rate: tot.apiErrors.rateLimit || 0, auth: tot.apiErrors.auth || 0 }),
    action: t('creditsAction'),
    doc: doc('model-config'),
    details: Object.entries(tot.apiErrors).map(([kind, n]) => t('errorCount', { kind, n })),
  })]
}

function longTurnFindings(digest, tot, { t, doc }) {
  const longTurns = tot.turns.filter((x) => x.maxMs >= THRESHOLDS.longTurnMs).length
  if (!longTurns) return []
  return [finding({
    id: 'cost-long-turns', severity: 'low',
    title: t('longTitle', { n: longTurns, min: THRESHOLDS.longTurnMs / 60000 }),
    evidence: t('longEvidence', { min: Math.round(Math.max(...tot.turns.map((x) => x.maxMs)) / 60000) }),
    action: t('longAction'),
    doc: doc('workflows'),
    details: topSessions(digest, (s) => s.turns?.maxMs || 0, (r) => t('longDetail', { label: sessionLabel(r.s), min: Math.round(r.v / 60000) })),
  })]
}

export function buildImprove(digest, ctx = makeCtx()) {
  const tot = totals(digest)
  return [
    ...reviewGateFindings(tot, ctx),
    ...recallFindings(tot, digest?.history || {}, ctx),
    ...correctionFindings(digest?.history || {}, ctx),
    ...toolErrorFindings(digest, ctx),
  ]
}

function reviewGateFindings(tot, ctx) {
  const { t, doc, cfg } = ctx
  if (!cfg.reviewers.length) return []
  const codeEdits = sum(Object.entries(tot.editExts).filter(([ext]) => CODE_EXTS.has(ext)).map(([, n]) => n))
  const reviewerRows = Object.entries(tot.agents).filter(([a]) => isReviewer(a, cfg.reviewers)).sort((a, b) => b[1] - a[1])
  const reviews = sum(reviewerRows.map(([, n]) => n))
  if (!codeEdits || reviews / codeEdits >= THRESHOLDS.reviewerRatioLow) return []
  const agents = cfg.reviewers.join(', ')
  return [finding({
    id: 'improve-review-gate', severity: 'high',
    title: t('gateTitle', { edits: codeEdits, reviews }),
    evidence: reviewerRows.map(([a, n]) => `${a.split(':').pop()} ${n}`).join(' · ') || t('gateNone'),
    action: t('gateAction'),
    doc: doc('hooks-guide'),
    details: reviewGateDetails(tot, reviewerRows, ctx),
    applyPrompt: t('gateApply', { agents }),
  })]
}

function reviewGateDetails(tot, reviewerRows, { t, cfg }) {
  const exts = Object.entries(tot.editExts).filter(([ext]) => CODE_EXTS.has(ext)).sort((a, b) => b[1] - a[1]).slice(0, DETAIL_ROWS)
  // Only the configured reviewer names are shown; other agent names may carry customer names.
  const others = sum(Object.entries(tot.agents).filter(([a]) => !isReviewer(a, cfg.reviewers)).map(([, n]) => n))
  return [
    ...exts.map(([ext, n]) => t('gateEdits', { ext, n })),
    ...reviewerRows.map(([a, n]) => t('gateReviewer', { name: a.split(':').pop(), n })),
    t('gateOthers', { n: others }),
  ]
}

// Searches of the user's notes: MCP tools by name prefix, CLIs by the first word of a Bash command.
function memorySearches(tot, memoryTools) {
  const tools = sum(Object.entries(tot.tools).filter(([k]) => memoryTools.some((p) => k.startsWith(p))).map(([, n]) => n))
  const clis = sum(Object.entries(tot.bashHeads).filter(([k]) => memoryTools.includes(k)).map(([, n]) => n))
  return tools + clis
}

function recallFindings(tot, h, { t, doc, cfg }) {
  // Without a configured note tool there is nothing to compare the cues against.
  if (!cfg.memoryTools.length) return []
  const searches = memorySearches(tot, cfg.memoryTools)
  const cues = h.memoryCuePrompts || 0
  if (cues <= searches) return []
  return [finding({
    id: 'improve-recall', severity: 'mid',
    title: t('recallTitle', { cues, searches }),
    evidence: t('recallEvidence'),
    action: t('recallAction'),
    doc: doc('hooks'),
  })]
}

function correctionFindings(h, { t, doc }) {
  // Phrases like "try again" turn up in any long history, so require a share of prompts as well.
  const n = h.correctionPrompts || 0
  if (n < THRESHOLDS.correctionHigh || n < (h.prompts || 0) * THRESHOLDS.correctionShare) return []
  return [finding({
    id: 'improve-corrections', severity: 'mid',
    title: t('correctionsTitle', { n: h.correctionPrompts }),
    evidence: t('correctionsEvidence'),
    action: t('correctionsAction'),
    doc: doc('best-practices'),
    applyPrompt: t('correctionsApply'),
  })]
}

function toolErrorFindings(digest, { t, doc }) {
  const denials = sum((digest?.sessions || []).map((s) => s.denials || 0))
  const errors = sum((digest?.sessions || []).map((s) => s.toolErrors || 0))
  if (errors < THRESHOLDS.toolErrorsHigh) return []
  return [finding({
    id: 'improve-tool-errors', severity: 'low',
    title: t('errorsTitle', { errors, denials }),
    evidence: t('errorsEvidence'),
    action: t('errorsAction'),
    doc: doc('memory'),
    details: topSessions(digest, (s) => s.toolErrors || 0, (r) => t('errorsDetail', { label: sessionLabel(r.s), n: r.v })),
  })]
}

export function buildStandup(digest, days, nowMs, gitLogs = {}, ctx = makeCtx()) {
  const since = nowMs - days * 24 * 3600 * 1000
  const byProject = new Map()
  for (const s of digest?.sessions || []) {
    if (!s.end || Date.parse(s.end) < since) continue
    // Sessions with neither a title nor a typed prompt (e.g. `claude -p /cmd`) carry no work to report.
    if (!s.title && !s.firstPrompt) continue
    const key = s.project || '(unknown)'
    const row = byProject.get(key) || { project: key, sessions: [], files: new Set() }
    row.sessions.push({ title: s.title || s.firstPrompt || ctx.t('untitled'), fromPrompt: !s.title, away: s.away?.at(-1) || null, end: s.end })
    for (const f of s.editedFiles || []) row.files.add(basename(f))
    byProject.set(key, row)
  }
  return [...byProject.values()]
    .map((r) => ({ ...r, files: [...r.files].slice(0, 8), commits: gitLogs[r.project] || [] }))
    .sort((a, b) => (b.sessions.at(-1)?.end || '').localeCompare(a.sessions.at(-1)?.end || ''))
}

export function rankFindings(list, dismissed = []) {
  const order = { high: 0, mid: 1, low: 2 }
  const hidden = new Set(dismissed)
  return list.filter((f) => !hidden.has(f.id)).sort((a, b) => order[a.severity] - order[b.severity])
}

files.hooks/i18n.js:
// Language, strings and the user-tunable rule settings, bundled into the ctx every rule takes.
// Pure functions, no mods API.

import { EN } from './strings-en.js'
import { JA } from './strings-ja.js'

const DICTS = { en: EN, ja: JA }
export const LANGUAGE_OPTIONS = ['auto', 'en', 'ja']

// `auto` follows Claude Code's own `language` setting ("Japanese", "日本語", "ja", ...).
export function resolveLang(option, settingsLanguage) {
  if (option === 'en' || option === 'ja') return option
  const s = String(settingsLanguage || '').toLowerCase()
  // "ja", "ja-JP", "Japanese", "日本語" (but not "Javanese").
  return /^ja([-_]|$)/.test(s) || s.includes('japan') || s.includes('日本') ? 'ja' : 'en'
}

export function makeT(lang) {
  const dict = DICTS[lang] || EN
  return (key, params = {}) => {
    const entry = key in dict ? dict[key] : EN[key]
    if (entry === undefined) return key
    return typeof entry === 'function' ? entry(params) : entry
  }
}

export const docUrl = (lang, slug) => `https://code.claude.com/docs/${lang === 'ja' ? 'ja' : 'en'}/${slug}`

const list = (value) => String(value ?? '').split(',').map((s) => s.trim()).filter(Boolean)

// Defaults suit anyone; people with their own agents or note tools extend them in /config.
export const RULE_DEFAULTS = Object.freeze({
  // Claude Code ships no review agent, so the review checks stay off until you name yours.
  reviewerAgents: '',
  memoryTools: '',
  memoryCueWords: '',
  extraRiskyCommands: '',
})

// Built-in words that mean "this needs earlier context", used when memoryCueWords is empty.
export const DEFAULT_MEMORY_CUES = ['前回', '以前', '覚えて', 'last time', 'previously', 'remember when']

export function ruleConfig(options = {}) {
  const get = (k) => (typeof options[k] === 'string' ? options[k] : RULE_DEFAULTS[k])
  const cues = list(get('memoryCueWords'))
  return Object.freeze({
    reviewers: Object.freeze(list(get('reviewerAgents'))),
    memoryTools: Object.freeze(list(get('memoryTools'))),
    memoryCues: Object.freeze(cues.length ? cues : DEFAULT_MEMORY_CUES),
    extraRisky: Object.freeze(list(get('extraRiskyCommands'))),
  })
}

export function makeCtx(lang = 'en', cfg = ruleConfig()) {
  return Object.freeze({ lang, t: makeT(lang), doc: (slug) => docUrl(lang, slug), cfg })
}

files.hooks/catalog.js:
// Claude Code features worth knowing, each with a usage check against the digest.
// Doc slugs were taken from https://code.claude.com/docs/llms.txt (2026-10-03); the same slug
// exists under /docs/en/ and /docs/ja/. A check returns null when the tip does not apply, or
// the params for its evidence string when it does.

import { totals } from './rules.js'
import { makeCtx } from './i18n.js'

const slash = (d, cmd) => d?.history?.slash?.[cmd] || 0
const tool = (tot, name) => tot.tools[name] || 0
// null when no permission-mode records exist, so tips don't fire on missing data.
const permRatio = (tot, mode) => {
  const all = Object.values(tot.permModes).reduce((a, b) => a + b, 0)
  return all ? (tot.permModes[mode] || 0) / all : null
}
const agents = (tot) => tool(tot, 'Agent') + tool(tot, 'Task') + tool(tot, 'Workflow')
const prompts = (d) => d.history?.prompts || 0
const redo = (d) => d.history?.correctionPrompts || 0

// Ordered by expected payoff; `key` names the tipXxxTitle / Concept / Evidence strings.
export const CATALOG = [
  {
    id: 'tip-loop', key: 'tipLoop', slug: 'scheduled-tasks',
    check: (d) => ((d.history?.resumePrompts || 0) >= 10 && slash(d, '/loop') < 3 ? { n: d.history.resumePrompts, loop: slash(d, '/loop') } : null),
  },
  {
    id: 'tip-context', key: 'tipContext', slug: 'context-window',
    check: (d, tot) => (slash(d, '/context') === 0 && tot.compactions.length >= 3 ? { n: tot.compactions.length } : null),
  },
  {
    id: 'tip-rewind', key: 'tipRewind', slug: 'checkpointing',
    check: (d) => (slash(d, '/rewind') === 0 && redo(d) >= 5 ? { n: redo(d) } : null),
  },
  {
    id: 'tip-plan-mode', key: 'tipPlan', slug: 'permission-modes',
    check: (d, tot) => {
      const r = permRatio(tot, 'plan')
      return r !== null && r < 0.03 && redo(d) >= 5 ? { pct: Math.round(r * 100), n: redo(d) } : null
    },
  },
  {
    id: 'tip-effort', key: 'tipEffort', slug: 'model-config',
    check: (d) => (slash(d, '/model') >= 30 && slash(d, '/effort') < 10 ? { model: slash(d, '/model'), effort: slash(d, '/effort') } : null),
  },
  {
    id: 'tip-hooks-checks', key: 'tipHooks', slug: 'hooks-guide',
    check: (d, tot) => {
      const r = permRatio(tot, 'auto')
      return r !== null && r >= 0.8 ? { pct: Math.round(r * 100) } : null
    },
  },
  {
    id: 'tip-worktree', key: 'tipWorktree', slug: 'worktrees',
    check: (d, tot) => (tool(tot, 'EnterWorktree') === 0 && agents(tot) >= 30 ? { n: agents(tot) } : null),
  },
  {
    id: 'tip-skills', key: 'tipSkills', slug: 'skills',
    check: (d, tot) => (tool(tot, 'Skill') < 20 && prompts(d) >= 300 ? { n: tool(tot, 'Skill'), prompts: prompts(d) } : null),
  },
  {
    id: 'tip-btw', key: 'tipBtw', slug: 'interactive-mode',
    check: (d) => (slash(d, '/btw') < 5 && prompts(d) >= 300 ? { n: slash(d, '/btw'), prompts: prompts(d) } : null),
  },
  {
    id: 'tip-output-style', key: 'tipStyle', slug: 'output-styles',
    check: (d) => (slash(d, '/output-style') === 0 && prompts(d) >= 500 ? {} : null),
  },
]

export const MAX_TIPS = 5

export function buildTips(digest, ctx = makeCtx(), catalog = CATALOG, limit = MAX_TIPS) {
  const { t, doc } = ctx
  const tot = totals(digest)
  const out = []
  for (const item of catalog) {
    let hit = null
    try {
      hit = item.check(digest || {}, tot)
    } catch {
      // A rule that cannot read this digest simply does not apply.
      hit = null
    }
    if (hit) out.push({ id: item.id, severity: 'low', title: t(item.key + 'Title'), evidence: t(item.key + 'Evidence', hit), action: t(item.key + 'Concept'), doc: doc(item.slug), details: [] })
  }
  return out.slice(0, limit)
}

files.hooks/view.js:
// Pane rendering. Receives the element functions from $.ui.resolve(e), plain callbacks from
// register.js and the strings function `model.t`, so this file never touches the mods API.

import { CREDIT_MODELS, EFFORT_OPTIONS, MODEL_OPTIONS } from './ai-config.js'

export const TABS = [
  { id: 'now', label: 'Now', hotkey: '1' },
  { id: 'cost', label: 'Cost', hotkey: '2' },
  { id: 'tips', label: 'Tips', hotkey: '3' },
  { id: 'standup', label: 'Standup', hotkey: '4' },
  { id: 'improve', label: 'Improve', hotkey: '5' },
]

const MARK = { high: '●', mid: '◐', low: '○' }
const COLOR = { high: 'error', mid: 'warning' }
const AI_TABS = new Set(['cost', 'tips', 'standup', 'improve'])
// Titles, recaps, commit subjects and file names come from transcripts: drop control characters.
// Bidi overrides and line/paragraph separators can disguise text, so they go too.
const CONTROL_CHARS = /[\u0000-\u0008\u000b-\u001f\u007f-\u009f\u2028\u2029\u202a-\u202e\u2066-\u2069]/g
const DETAIL_MAX = 12
const clean = (text) => String(text ?? '').replace(CONTROL_CHARS, '')
const folder = (p) => String(p || '').split(/[\\/]/).filter(Boolean).slice(-2).join('/')

export function renderPane(el, model, h) {
  const { Box } = el
  if (model.detail) return renderDetail(el, model, h)
  return Box({
    flexDirection: 'column',
    rowGap: 1,
    children: [tabRow(el, model, h), statusLine(el, model, h), ...body(el, model, h), aiBlock(el, model, h)].filter(Boolean),
  })
}

function tabRow(el, model, h) {
  const { Box, Button } = el
  return Box({
    flexDirection: 'row',
    columnGap: 2,
    flexWrap: 'wrap',
    children: TABS.map((tab) => Button({
      key: 'tab-' + tab.id,
      label: tab.label + countBadge(model, tab.id),
      hotkey: tab.hotkey,
      plain: true,
      ...(model.tab === tab.id ? {} : { dimColor: true }),
      onPress: () => h.onTab(tab.id),
    })),
  })
}

function countBadge(model, tab) {
  const n = model.lists[tab]?.length
  return n ? ` (${n})` : ''
}

function statusLine(el, model, h) {
  const { Box, Text, Button } = el
  const { t, status: s } = model
  const text = s.error ? t('indexError', { error: s.error })
    : s.indexing ? t('indexing')
    : s.generatedAt ? t('indexed', { at: s.generatedAt.slice(0, 16).replace('T', ' '), n: s.sessions })
    : t('notIndexed')
  return Box({
    flexDirection: 'row',
    columnGap: 2,
    children: [
      Text({ dimColor: true, wrap: 'truncate-end', children: [clean(text)] }),
      model.versionWarning ? Text({ color: 'warning', wrap: 'truncate-end', children: [t('oldVersion', model.versionWarning)] }) : null,
      Button({ key: 'refresh', label: t('refresh'), hotkey: 'r', plain: true, onPress: () => h.onRefresh() }),
    ].filter(Boolean),
  })
}

function body(el, model, h) {
  if (model.tab === 'standup') return standup(el, model, h)
  const list = model.lists[model.tab] || []
  if (!list.length) return [el.Text({ dimColor: true, children: [model.t(model.tab === 'now' ? 'emptyNow' : 'emptyList')] })]
  return list.map((f) => findingCard(el, model.t, f, h))
}

function findingCard(el, t, f, h) {
  const { Box, Text, Button, Link } = el
  const actions = [
    Button({ key: 'ask-' + f.id, label: t('ask'), onPress: () => h.onAsk(f) }),
    f.applyPrompt ? Button({ key: 'apply-' + f.id, label: t('apply'), onPress: () => h.onApply(f) }) : null,
    Button({ key: 'hide-' + f.id, label: t('dismiss'), onPress: () => h.onDismiss(f) }),
    f.doc ? Link({ href: f.doc, label: t('docs') }) : null,
  ].filter(Boolean)
  return Box({
    key: 'card-' + f.id,
    flexDirection: 'column',
    children: [
      Text({ bold: true, ...(COLOR[f.severity] ? { color: COLOR[f.severity] } : {}), children: [clean(`${MARK[f.severity]} ${f.title}`)] }),
      Text({ dimColor: true, children: [clean('  ' + f.evidence)] }),
      Text({ children: [clean('  → ' + f.action)] }),
      Box({ flexDirection: 'row', columnGap: 1, flexWrap: 'wrap', children: actions }),
    ],
  })
}

function standup(el, model, h) {
  const { Box, Text, Button } = el
  const { t } = model
  const header = Box({
    flexDirection: 'row',
    columnGap: 2,
    children: [1, 3, 7].map((d) => Button({
      key: 'days-' + d, label: t('days', { d }), plain: true,
      ...(model.days === d ? {} : { dimColor: true }),
      onPress: () => h.onDays(d),
    })),
  })
  if (!model.standup.length) return [header, Text({ dimColor: true, children: [t('noSessions', { d: model.days })] })]
  return [header, ...model.standup.map((row) => Box({
    key: 'su-' + row.project,
    flexDirection: 'column',
    children: [
      Text({ bold: true, children: [clean('■ ' + folder(row.project))] }),
      ...row.sessions.slice(-4).map((s) => Text({ children: [clean('  • ' + s.title)] })),
      ...row.sessions.filter((s) => s.away).slice(-1).map((s) => Text({ dimColor: true, children: [clean('  ' + t('recap') + s.away)] })),
      row.commits.length ? Text({ dimColor: true, children: [clean('  ' + t('commits') + row.commits.slice(0, 5).join(' / '))] }) : null,
      row.files.length ? Text({ dimColor: true, wrap: 'truncate-end', children: [clean('  ' + t('files') + row.files.join(', '))] }) : null,
    ].filter(Boolean),
  }))]
}

function aiBlock(el, model, h) {
  if (!AI_TABS.has(model.tab)) return null
  const { Box, Button, Markdown, Text } = el
  const { t } = model
  const ai = model.ai[model.tab]
  const children = [Button({ key: 'ai-' + model.tab, label: ai?.loading ? t('summarizing') : t('summarize', { model: model.settings.model }), hotkey: 'a', onPress: () => h.onAi(model.tab) })]
  if (ai?.text) children.push(Markdown({ key: 'ai-text-' + model.tab, text: clean(ai.text).slice(0, 9000) }))
  if (ai?.error) children.push(Text({ color: 'error', children: [clean(t('summaryFailed', { error: ai.error }))] }))
  children.push(Text({ dimColor: true, children: [t('summaryNote')] }))
  return Box({ flexDirection: 'column', children })
}

// Details: the finding's numbers, the rule's breakdown and an AI explanation, all inside the pane.
function renderDetail(el, model, h) {
  const { Box, Text, Code } = el
  const { t } = model
  const f = model.detail
  const details = f.details || []
  const shown = details.slice(0, DETAIL_MAX).map((d) => Text({ children: [clean('  • ' + d)] }))
  if (details.length > DETAIL_MAX) shown.push(Text({ dimColor: true, children: [t('more', { n: details.length - DETAIL_MAX })] }))
  return Box({
    flexDirection: 'column',
    rowGap: 1,
    children: [
      detailActions(el, t, f, h),
      f.isResolved ? Text({ color: 'success', children: [t('resolved')] }) : null,
      Text({ bold: true, ...(COLOR[f.severity] ? { color: COLOR[f.severity] } : {}), children: [clean(`${MARK[f.severity]} ${f.title}`)] }),
      Text({ dimColor: true, children: [clean(f.evidence)] }),
      shown.length ? Box({ flexDirection: 'column', children: [Text({ bold: true, children: [t('breakdown')] }), ...shown] }) : null,
      Box({ flexDirection: 'column', children: [Text({ bold: true, children: [t('actionHead')] }), Text({ children: [clean('  ' + f.action)] })] }),
      Box({ flexDirection: 'column', children: [Text({ bold: true, children: [t('promptHead')] }), Code({ source: clean(f.copyText) })] }),
      explainBlock(el, model, h),
    ].filter(Boolean),
  })
}

function detailActions(el, t, f, h) {
  const { Box, Button, Link } = el
  return Box({
    flexDirection: 'row',
    columnGap: 2,
    flexWrap: 'wrap',
    children: [
      Button({ key: 'back', label: t('back'), hotkey: 'b', plain: true, onPress: () => h.onBack() }),
      Button({ key: 'copy-' + f.id, label: t('copy'), hotkey: 'c', plain: true, onPress: (press) => h.onCopy(f.copyText, press) }),
      f.applyPrompt ? Button({ key: 'apply-' + f.id, label: t('applyChat'), onPress: () => h.onApply(f) }) : null,
      f.doc ? Link({ href: f.doc, label: t('docs') }) : null,
    ].filter(Boolean),
  })
}

function explainBlock(el, model, h) {
  const { Box, Text, Button, Markdown } = el
  const { t } = model
  const f = model.detail
  const ex = model.explain
  const body = ex?.loading ? [Text({ dimColor: true, children: [t('explaining', { model: ex.model })] })]
    : ex?.error ? [Text({ color: 'error', children: [clean(t('explainFailed', { error: ex.error }))] })]
    : ex?.text ? [Markdown({ key: 'explain-' + f.id, text: clean(ex.text).slice(0, 9000) }), Text({ dimColor: true, children: [usageLine(t, ex)] })]
    : [Text({ dimColor: true, children: [generateHint(t, model.settings)] })]
  return Box({
    flexDirection: 'column',
    children: [
      Box({ flexDirection: 'row', columnGap: 2, children: [Text({ bold: true, children: [t('explainHead')] }), Button({ key: 'explain-again', label: t(ex?.text ? 'regenerate' : 'generate'), hotkey: 'g', plain: true, onPress: () => h.onExplainAgain(f) })] }),
      ...body,
      settingsRow(el, model, h),
      Text({ dimColor: true, children: [t(f.localDetails ? 'sendLocal' : 'sendDetail')] }),
    ],
  })
}

// Why there is no explanation yet, so the hint never claims a setting that is not in effect.
function generateHint(t, settings) {
  if (!settings.autoExplain) return t('hintOff')
  if (CREDIT_MODELS.has(settings.model)) return t('hintCredit', { model: settings.model })
  return t('hint')
}

function usageLine(t, ex) {
  if (ex.isCached) return t('cached', { model: ex.model })
  return ex.tokens ? t('usage', { model: ex.model, in: ex.tokens.in, out: ex.tokens.out }) : ex.model || ''
}

// Model and effort pickers; a change is saved to this plugin's /config fields.
function settingsRow(el, model, h) {
  const { Box, Text, Select } = el
  const { t, settings, aiUsage } = model
  return Box({
    flexDirection: 'column',
    children: [
      Box({
        flexDirection: 'row',
        columnGap: 2,
        flexWrap: 'wrap',
        children: [
          Select({ key: 'ai-model', label: t('modelLabel'), value: settings.model, options: MODEL_OPTIONS.map((m) => ({ value: m, label: CREDIT_MODELS.has(m) ? t('creditLabel', { model: m }) : m })), onSelect: (v) => h.onSetting('aiModel', v) }),
          Select({ key: 'ai-effort', label: 'effort', value: settings.effort, options: EFFORT_OPTIONS.map((x) => ({ value: x, label: x })), onSelect: (v) => h.onSetting('aiEffort', v) }),
        ],
      }),
      Text({ dimColor: true, children: [t('sessionUsage', aiUsage)] }),
    ],
  })
}

files.hooks/privacy.js:
// What may leave the machine, in one place. Pure functions, no mods API.
// Contract: model payloads carry counts, model names, dates and project folder basenames —
// never prompt text, paths or file names. Builders only emit counts and fixed wording; this
// filter is a backstop that withholds anything that looks like a path, URL or control text.

import { makeT } from './i18n.js'

const MAX_SHARED_LINE = 160
// A shareable line has no path-like token, no control characters and a bounded length.
const CONTROL = /[\u0000-\u001f\u007f-\u009f\u2028\u2029\u202a-\u202e\u2066-\u2069]/
// Path-like: a token with two or more "/", one starting with ~/ ./ ../ or /x/, a slash token
// ending in a file extension (src/a.py, /x.txt), a URL scheme, a fullwidth slash or any backslash.
const PATH_LIKE = /(^|\s)(~|\.{1,2})?\/[^\s/]+\/|[^\s/]+\/[^\s/]+\/|(^|\s)(~|\.{1,2})\/|\S*\/[^\s/]+\.[A-Za-z0-9]{1,6}(?=\s|$)|:\/\/|\uff0f|\\/
export const isShareableLine = (s) => typeof s === 'string' && s.length <= MAX_SHARED_LINE && !CONTROL.test(s) && !PATH_LIKE.test(s)

// The finding as the model may see it. localDetails findings name files: send only a count.
export function shareableFinding(f, t = makeT('en')) {
  const details = Array.isArray(f.details) ? f.details : []
  const local = f.localDetails === true
  return {
    title: isShareableLine(f.title) ? f.title : t('withheld'),
    evidence: local ? t('localEvidence', { n: details.length }) : isShareableLine(f.evidence) ? f.evidence : t('withheld'),
    action: f.action,
    severity: f.severity,
    topic: typeof f.doc === 'string' ? f.doc.split('/').filter(Boolean).pop() : null,
    details: local ? [] : details.filter(isShareableLine),
  }
}

// Every finding offers a prompt to copy; rule-specific prompts win.
export function copyText(f, t = makeT('en')) {
  return f.prompt || t('copyFallback', { title: f.title, evidence: f.evidence, doc: f.doc || t('none') })
}

// Model output is shown as Markdown; drop links of any scheme and reference-style links.
export function stripLinks(text) {
  return String(text)
    .replace(/^\s*\[[^\]]+\]:\s*\S+.*$/gm, '')
    .replace(/!?\[([^\]]*)\]\([^)]*\)/g, '$1')
    .replace(/!?\[([^\]]*)\]\[[^\]]*\]/g, '$1')
    .replace(/<?\b(?:[a-z][a-z0-9+.-]*:\/\/|mailto:|javascript:|data:|file:)[^\s>)]*>?/gi, '[link removed]')
}

files.hooks/ai-config.js:
// Model settings, prompts and the persistent explanation cache. Pure functions, no mods API.

import { LANGUAGE_OPTIONS } from './i18n.js'

export const MODEL_OPTIONS = ['haiku', 'sonnet', 'opus', 'fable']
export const EFFORT_OPTIONS = ['low', 'medium', 'high']
export const DEFAULT_SETTINGS = Object.freeze({ model: 'haiku', effort: 'low', autoExplain: true, cacheExplanations: true, language: 'auto' })
// Models billed to usage credits: never called without an explicit press.
export const CREDIT_MODELS = new Set(['fable'])
const CACHE_TEXT_MAX = 9000
// Short answers keep output tokens bounded; the prompts ask for the same length. Higher effort
// may spend part of the cap on thinking, so the cap grows with it rather than cutting the reply.
const MAX_TOKENS_BY_EFFORT = Object.freeze({ low: 700, medium: 1200, high: 2000 })
export const maxTokensFor = (settings) => MAX_TOKENS_BY_EFFORT[settings.effort] || MAX_TOKENS_BY_EFFORT.low
const CACHE_MAX_ENTRIES = 40
const CACHE_TTL_MS = 14 * 24 * 3600 * 1000
// Bump when the prompts change so cached answers from old prompts are not reused.
const PROMPT_VERSION = 3

// System prompts in the pane's language; the untrusted-data rule is always appended.
export function systemPrompt(kind, t) {
  return [t(kind === 'explain' ? 'explainSystem' : 'summarySystem'), t('untrusted')].join('\n')
}

// userConfig values (or a /config change) -> settings; unknown values fall back to defaults.
export function normalizeSettings(options = {}) {
  const pick = (value, allowed, fallback) => (allowed.includes(value) ? value : fallback)
  return Object.freeze({
    model: pick(options.aiModel, MODEL_OPTIONS, DEFAULT_SETTINGS.model),
    effort: pick(options.aiEffort, EFFORT_OPTIONS, DEFAULT_SETTINGS.effort),
    autoExplain: typeof options.autoExplain === 'boolean' ? options.autoExplain : DEFAULT_SETTINGS.autoExplain,
    cacheExplanations: typeof options.cacheExplanations === 'boolean' ? options.cacheExplanations : DEFAULT_SETTINGS.cacheExplanations,
    language: pick(options.language, LANGUAGE_OPTIONS, DEFAULT_SETTINGS.language),
  })
}

// Settings with one userConfig field replaced (aiModel | aiEffort | autoExplain).
export function mergeSetting(settings, field, value) {
  const current = { aiModel: settings.model, aiEffort: settings.effort, autoExplain: settings.autoExplain, cacheExplanations: settings.cacheExplanations, language: settings.language }
  return normalizeSettings({ ...current, [field]: value })
}

const FIELDS = ['aiModel', 'aiEffort', 'autoExplain', 'cacheExplanations', 'language']

// The userConfig field a /config key names, when it is one of ours. A --plugin-dir load may key
// the plugin as `<name>` or `<name>@inline`, so both `<name>.<field>` and `<name>@x.<field>` match.
export function settingsField(key, pluginName) {
  if (typeof key !== 'string' || typeof pluginName !== 'string') return null
  const head = key.slice(0, key.lastIndexOf('.'))
  const field = key.slice(key.lastIndexOf('.') + 1)
  const isOurs = head === pluginName || head.startsWith(pluginName + '@')
  return isOurs && FIELDS.includes(field) ? field : null
}

// Two FNV-1a passes with different offsets: a stable 64-bit key, dependency-free (not for security).
function fnv1a(text, seed) {
  let h = seed
  for (let i = 0; i < text.length; i += 1) {
    h ^= text.charCodeAt(i)
    h = Math.imul(h, 0x01000193) >>> 0
  }
  return h.toString(16).padStart(8, '0')
}

// Same finding content + model/effort + language + prompt version + exclusions -> same answer.
// Exclusions are part of the key so changing excludeProjects never surfaces older answers.
export function explainCacheKey(payload, settings, excludes = [], lang = 'en') {
  const text = JSON.stringify([PROMPT_VERSION, lang, settings.model, settings.effort, [...excludes].sort(), payload])
  return fnv1a(text, 0x811c9dc5) + fnv1a(text, 0x050c5d1f)
}

// The store is a shared JSON file: accept only well-formed entries from it.
export function isCacheEntry(v) {
  return Boolean(v) && typeof v.text === 'string' && v.text.length <= CACHE_TEXT_MAX && MODEL_OPTIONS.includes(v.model) && Number.isFinite(v.at)
}

// Drop expired entries and keep the newest CACHE_MAX_ENTRIES, so $.store stays small.
export function pruneCache(cache, nowMs) {
  const live = Object.entries(cache || {}).filter(([, v]) => isCacheEntry(v) && nowMs - v.at < CACHE_TTL_MS)
  return Object.fromEntries(live.sort((a, b) => b[1].at - a[1].at).slice(0, CACHE_MAX_ENTRIES))
}

// One definition for every token figure shown: input counts cached and cache-written tokens too.
export function tokensOf(usage) {
  return {
    in: (usage?.input_tokens || 0) + (usage?.cache_read_input_tokens || 0) + (usage?.cache_creation_input_tokens || 0),
    out: usage?.output_tokens || 0,
  }
}

export function addUsage(total, usage) {
  const t = tokensOf(usage)
  return { calls: total.calls + 1, in: total.in + t.in, out: total.out + t.out }
}

files.types/index.d.ts:
// $.state values: the host keeps them for the session across module reloads (an options change
// reloads the plugin). The mod rewrites them to defaults itself on /clear, /resume and /branch.
declare module 'claude-code' {
  interface PluginState {
    'ccmod-chronicle': {
      view: {
        tab: string
        detailId: string | null
        days: number
        aiUsage: { calls: number; in: number; out: number }
        // Explanations of live now-* findings (digest ones are cached in $.store).
        nowExplain: Record<string, { text: string; model: string; tokens?: { in: number; out: number } }>
        // Live signals buildNow needs: code files edited since the last review, risky command counts.
        live: { unreviewed: string[]; risky: Record<string, number> }
        sessionDismissed: string[]
      }
    }
  }
}
